// Dashboard composition. Owned by the integration session: build sessions do not edit this file.
import { ConveyorRouteMap } from './components/conveyor/ConveyorRouteMap';
import { ExposureGauge } from './components/exposure/ExposureGauge';
import { KpiRow } from './components/exposure/KpiRow';
import { RecommendationCard } from './components/exposure/RecommendationCard';
import { ActiveToolCard } from './components/ops/ActiveToolCard';
import { DefectCard } from './components/ops/DefectCard';
import { LiveSensorCard } from './components/ops/LiveSensorCard';
import { WorkerStatusCard } from './components/ops/WorkerStatusCard';
import { WorkOrderCard } from './components/ops/WorkOrderCard';
import { ShiftTimeline } from './components/timeline/ShiftTimeline';
import { useShift } from './api/useShift';
import { useVexoBand } from './band/useVexoBand';
import { shift } from './data/shift';
import { HeroHeader } from './layout/HeroHeader';
import { SectionBoundary } from './layout/SectionBoundary';
import { PlanOptions } from './layout/PlanOptions';
import { withToolActivity } from './data/toolActivity';
import { Sidebar } from './layout/Sidebar';
import { TopBar } from './layout/TopBar';

export default function App() {
  // The BeltGuard server owns the band and builds the shift; demo data when it is offline.
  const { data: d, mode } = useShift(shift);
  // The browser owns the band link (like the kit dashboard) and forwards readings to the server.
  const vexo = useVexoBand(shift.band);
  const browserBand = vexo.state.source !== 'mock';
  const band = browserBand ? vexo.state : mode === 'server' ? d.band : vexo.state;
  return (
    <div className="flex min-h-full">
      <Sidebar />
      <main className="min-w-0 flex-1 px-5 py-5 lg:px-8">
        <div className="mx-auto flex max-w-[1560px] flex-col gap-5">
          <TopBar conveyor={d.conveyor} mode={mode} replay={Boolean(d.replay)} vexo={vexo} />
          {vexo.state.error && (
            <p role="alert" className="rounded-xl border border-warn/40 bg-warn-bg px-4 py-2.5 text-sm text-ink">
              {vexo.state.error}
            </p>
          )}
          <SectionBoundary name="Header"><HeroHeader conveyor={d.conveyor} shift={d.shift} /></SectionBoundary>

          <SectionBoundary name="KPIs"><KpiRow kpis={d.kpis} /></SectionBoundary>

          <div className="grid grid-cols-12 items-start gap-5">
            <div className="col-span-12 xl:col-span-8">
              <SectionBoundary name="Conveyor route map"><ConveyorRouteMap conveyor={withToolActivity(d.conveyor, d.tool)} defect={d.defect} /></SectionBoundary>
            </div>
            <div className="col-span-12 flex flex-col gap-5 xl:col-span-4">
              <SectionBoundary name="HAV exposure"><ExposureGauge exposure={d.exposure} /></SectionBoundary>
              <SectionBoundary name="Recommendation"><RecommendationCard recommendation={d.recommendation} exposure={d.exposure} /></SectionBoundary>
              <SectionBoundary name="Alternative plans"><PlanOptions enabled={mode === 'server'} /></SectionBoundary>
            </div>
          </div>

          <div className="grid grid-cols-12 gap-5">
            <div className="col-span-12 md:col-span-6 xl:col-span-3"><SectionBoundary name="Workers"><WorkerStatusCard workers={d.workers} /></SectionBoundary></div>
            <div className="col-span-12 md:col-span-6 xl:col-span-5"><SectionBoundary name="Vexo band"><LiveSensorCard band={band} controls={vexo} /></SectionBoundary></div>
            <div className="col-span-12 md:col-span-6 xl:col-span-4"><SectionBoundary name="Active tool"><ActiveToolCard tool={d.tool} /></SectionBoundary></div>
            <div className="col-span-12 md:col-span-6 xl:col-span-6"><SectionBoundary name="Defect"><DefectCard defect={d.defect} /></SectionBoundary></div>
            <div className="col-span-12 xl:col-span-6"><SectionBoundary name="Work order"><WorkOrderCard workOrder={d.workOrder} /></SectionBoundary></div>
          </div>

          <SectionBoundary name="Timeline"><ShiftTimeline events={d.events} conveyorId={d.conveyor.id} /></SectionBoundary>
        </div>
      </main>
    </div>
  );
}
